import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.CWdVbaJB.js";const m=JSON.parse('{"title":"Projects","description":"","frontmatter":{"title":"Projects"},"headers":[],"relativePath":"platform/projects.md","filePath":"platform/projects.md"}'),i={name:"platform/projects.md"};function s(c,e,d,l,n,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h1><p>Projects organize your traces, findings, and API keys into isolated groups within a workspace. Use projects to separate environments, teams, or applications.</p><h2 id="creating-a-project" tabindex="-1">Creating a Project <a class="header-anchor" href="#creating-a-project" aria-label="Permalink to &quot;Creating a Project&quot;">​</a></h2><ol><li>Navigate to the <strong>Admin</strong> tab</li><li>Click <strong>New Project</strong></li><li>Enter a project name — a URL-friendly slug is generated automatically</li></ol><p>Only workspace admins can create projects.</p><h2 id="project-features" tabindex="-1">Project Features <a class="header-anchor" href="#project-features" aria-label="Permalink to &quot;Project Features&quot;">​</a></h2><h3 id="trace-isolation" tabindex="-1">Trace Isolation <a class="header-anchor" href="#trace-isolation" aria-label="Permalink to &quot;Trace Isolation&quot;">​</a></h3><p>Each trace can be tagged to a project. Use project-scoped API keys to automatically tag traces on ingest, or set the <code>projectId</code> field in your SDK.</p><h3 id="rbac" tabindex="-1">RBAC <a class="header-anchor" href="#rbac" aria-label="Permalink to &quot;RBAC&quot;">​</a></h3><p>Project membership controls who can see project data:</p><ul><li><strong>Admins</strong> see all projects in the workspace</li><li><strong>Members</strong> see only projects they&#39;ve been added to</li><li>Workspace-level data (traces without a project) is visible to everyone</li></ul><h3 id="per-project-api-keys" tabindex="-1">Per-Project API Keys <a class="header-anchor" href="#per-project-api-keys" aria-label="Permalink to &quot;Per-Project API Keys&quot;">​</a></h3><p>Create API keys scoped to a specific project in <strong>Settings &gt; API Keys</strong>. Traces ingested with a project-scoped key are automatically tagged to that project.</p><h2 id="managing-members" tabindex="-1">Managing Members <a class="header-anchor" href="#managing-members" aria-label="Permalink to &quot;Managing Members&quot;">​</a></h2><ol><li>In the Admin tab, find the project row</li><li>Click the <strong>Members</strong> icon</li><li>Use the checkboxes to add or remove users</li><li>Changes save automatically</li></ol><p>Members can be assigned roles at the project level.</p><h2 id="archiving-projects" tabindex="-1">Archiving Projects <a class="header-anchor" href="#archiving-projects" aria-label="Permalink to &quot;Archiving Projects&quot;">​</a></h2><p>Archiving a project:</p><ol><li>Hides it from the default project list</li><li>Schedules hard deletion after <strong>30 days</strong></li><li>Shows a warning banner to project members</li></ol><h3 id="restore" tabindex="-1">Restore <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Restore&quot;">​</a></h3><p>Archived projects can be restored within the 30-day window:</p><ol><li>Find the project in the archived list</li><li>Click <strong>Restore</strong></li><li>The deletion timer is reset</li></ol><h3 id="hard-deletion" tabindex="-1">Hard Deletion <a class="header-anchor" href="#hard-deletion" aria-label="Permalink to &quot;Hard Deletion&quot;">​</a></h3><p>After 30 days, an automated process permanently deletes:</p><ul><li>All traces in the project</li><li>All findings in the project</li><li>All ingest events</li><li>All cost ledger entries</li><li>The project record itself</li></ul><p>A warning email is sent at day 25 to workspace admins.</p><h3 id="banner-dismissal" tabindex="-1">Banner Dismissal <a class="header-anchor" href="#banner-dismissal" aria-label="Permalink to &quot;Banner Dismissal&quot;">​</a></h3><p>The archive warning banner can be dismissed per user. Dismissals are archive-cycle-aware — if a project is restored and re-archived, the banner reappears.</p><h2 id="audit-trail" tabindex="-1">Audit Trail <a class="header-anchor" href="#audit-trail" aria-label="Permalink to &quot;Audit Trail&quot;">​</a></h2><p>All project actions are logged:</p><table tabindex="0"><thead><tr><th>Event</th><th>Description</th></tr></thead><tbody><tr><td><code>project.created</code></td><td>New project created</td></tr><tr><td><code>project.renamed</code></td><td>Project name changed</td></tr><tr><td><code>project.archived</code></td><td>Project archived</td></tr><tr><td><code>project.restored</code></td><td>Project restored from archive</td></tr><tr><td><code>project.hard_deleted</code></td><td>Project permanently deleted</td></tr><tr><td><code>project_member.added</code></td><td>User added to project</td></tr><tr><td><code>project_member.removed</code></td><td>User removed from project</td></tr><tr><td><code>project_member.role_changed</code></td><td>Member role updated</td></tr></tbody></table>',31)])])}const j=t(i,[["render",s]]);export{m as __pageData,j as default};
